// Initialize arrays to collect data
let allClassifications = [];
let totalSummary = { total: 0, matches: 0, no_matches: 0, uncertain: 0 };

// 1. Loop through all input items
for (const item of $input.all()) {
  let rawOutput = item.json.output;

  if (typeof rawOutput === 'string' && rawOutput.trim() !== "") {
    // Clean Markdown formatting with safe regex
    // The "missing /" error usually happens here if the line is incomplete
    const cleanedOutput = rawOutput
      .replace(/```json\s*/g, '')
      .replace(/```\s*/g, '')
      .trim();

    try {
      const parsed = JSON.parse(cleanedOutput);

      if (parsed.classifications) {
        allClassifications.push(...parsed.classifications);
      }

      if (parsed.summary) {
        totalSummary.total += (Number(parsed.summary.total) || 0);
        totalSummary.matches += (Number(parsed.summary.matches) || 0);
        totalSummary.no_matches += (Number(parsed.summary.no_matches) || 0);
        totalSummary.uncertain += (Number(parsed.summary.uncertain) || 0);
      }
    } catch (e) {
      // Skip items that can't be parsed
      continue;
    }
  }
}

// 2. Safely reference the Amazon product node
let amazonProducts = [];
try {
  const amazonNode = $('Deduplicate + Combine Final Amazon Product List');
  if (amazonNode && amazonNode.length > 0) {
    amazonProducts = amazonNode.first().json.amazonProducts || [];
  }
} catch (e) {
  // If the node hasn't run yet, we keep amazonProducts as an empty array
}

// 3. Filter to only matching products
const matchingUrls = new Set(
  allClassifications
    .filter(c => c.match_status === 'match' && c.confidence !== 'low')
    .map(c => c.url)
);

const filteredProducts = amazonProducts
  .filter(p => matchingUrls.has(p.url))
  .map(p => {
    const classification = allClassifications.find(c => c.url === p.url);
    return {
      ...p,
      classification_reasoning: classification?.reasoning || ''
    };
  });

// 4. Return result
return [{
  json: {
    filteredProducts: filteredProducts,
    totalFiltered: filteredProducts.length,
    classificationSummary: totalSummary
  }
}];

// Parse attribute extraction output
let output = $input.first().json.output;

if (typeof output === 'string') {
  output = output.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  try {
    output = JSON.parse(output);
  } catch (e) {
    return [{ json: { error: 'Failed to parse attributes', attributeData: null } }];
  }
}

return [{
  json: {
    attributeData: output,
    products: output.products || [],
    summary: output.summary || {}
  }
}];

